class TankImage extends DataClass implements Insertable<TankImage> {
  /// Primary key
  final int id;

  /// Foreign key to tank
  final int tankId;

  /// Image file path (local storage)
  final String imagePath;

  /// Optional caption/description
  final String? caption;

  /// Whether this is the cover/primary image for the tank
  final bool isCover;

  /// Date the photo was taken (if available)
  final DateTime? takenAt;

  /// Created timestamp
  final DateTime createdAt;
  const TankImage({
    required this.id,
    required this.tankId,
    required this.imagePath,
    this.caption,
    required this.isCover,
    this.takenAt,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['tank_id'] = Variable<int>(tankId);
    map['image_path'] = Variable<String>(imagePath);
    if (!nullToAbsent || caption != null) {
      map['caption'] = Variable<String>(caption);
    }
    map['is_cover'] = Variable<bool>(isCover);
    if (!nullToAbsent || takenAt != null) {
      map['taken_at'] = Variable<DateTime>(takenAt);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  TankImagesCompanion toCompanion(bool nullToAbsent) {
    return TankImagesCompanion(
      id: Value(id),
      tankId: Value(tankId),
      imagePath: Value(imagePath),
      caption: caption == null && nullToAbsent
          ? const Value.absent()
          : Value(caption),
      isCover: Value(isCover),
      takenAt: takenAt == null && nullToAbsent
          ? const Value.absent()
          : Value(takenAt),
      createdAt: Value(createdAt),
    );
  }

  factory TankImage.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return TankImage(
      id: serializer.fromJson<int>(json['id']),
      tankId: serializer.fromJson<int>(json['tankId']),
      imagePath: serializer.fromJson<String>(json['imagePath']),
      caption: serializer.fromJson<String?>(json['caption']),
      isCover: serializer.fromJson<bool>(json['isCover']),
      takenAt: serializer.fromJson<DateTime?>(json['takenAt']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'tankId': serializer.toJson<int>(tankId),
      'imagePath': serializer.toJson<String>(imagePath),
      'caption': serializer.toJson<String?>(caption),
      'isCover': serializer.toJson<bool>(isCover),
      'takenAt': serializer.toJson<DateTime?>(takenAt),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  TankImage copyWith({
    int? id,
    int? tankId,
    String? imagePath,
    Value<String?> caption = const Value.absent(),
    bool? isCover,
    Value<DateTime?> takenAt = const Value.absent(),
    DateTime? createdAt,
  }) => TankImage(
    id: id ?? this.id,
    tankId: tankId ?? this.tankId,
    imagePath: imagePath ?? this.imagePath,
    caption: caption.present ? caption.value : this.caption,
    isCover: isCover ?? this.isCover,
    takenAt: takenAt.present ? takenAt.value : this.takenAt,
    createdAt: createdAt ?? this.createdAt,
  );
  TankImage copyWithCompanion(TankImagesCompanion data) {
    return TankImage(
      id: data.id.present ? data.id.value : this.id,
      tankId: data.tankId.present ? data.tankId.value : this.tankId,
      imagePath: data.imagePath.present ? data.imagePath.value : this.imagePath,
      caption: data.caption.present ? data.caption.value : this.caption,
      isCover: data.isCover.present ? data.isCover.value : this.isCover,
      takenAt: data.takenAt.present ? data.takenAt.value : this.takenAt,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('TankImage(')
          ..write('id: $id, ')
          ..write('tankId: $tankId, ')
          ..write('imagePath: $imagePath, ')
          ..write('caption: $caption, ')
          ..write('isCover: $isCover, ')
          ..write('takenAt: $takenAt, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode =>
      Object.hash(id, tankId, imagePath, caption, isCover, takenAt, createdAt);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is TankImage &&
          other.id == this.id &&
          other.tankId == this.tankId &&
          other.imagePath == this.imagePath &&
          other.caption == this.caption &&
          other.isCover == this.isCover &&
          other.takenAt == this.takenAt &&
          other.createdAt == this.createdAt);
