class WaterParameter extends DataClass implements Insertable<WaterParameter> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Measurement timestamp
  final DateTime measuredAt;

  /// Temperature in Celsius
  final double? temperatureCelsius;

  /// pH level (0-14)
  final double? ph;

  /// Ammonia in ppm
  final double? ammoniaPpm;

  /// Nitrite in ppm
  final double? nitritePpm;

  /// Nitrate in ppm
  final double? nitratePpm;

  /// General Hardness (GH) in dGH
  final double? ghDgh;

  /// Carbonate Hardness (KH) in dKH
  final double? khDkh;

  /// Phosphate in ppm
  final double? phosphatePpm;

  /// Dissolved oxygen in mg/L
  final double? oxygenMgL;

  /// Carbon dioxide in mg/L
  final double? co2MgL;

  /// Salinity in ppt (for saltwater)
  final double? salinityPpt;

  /// Calcium in ppm (for reef tanks)
  final double? calciumPpm;

  /// Magnesium in ppm (for reef tanks)
  final double? magnesiumPpm;

  /// Alkalinity in dKH (for reef tanks)
  final double? alkalinityDkh;

  /// TDS (Total Dissolved Solids) in ppm
  final double? tdsPpm;

  /// Chlorine in ppm
  final double? chlorinePpm;

  /// Iron in ppm (for planted tanks)
  final double? ironPpm;

  /// Copper in ppm
  final double? copperPpm;

  /// Notes for this reading
  final String? notes;

  /// Created timestamp
  final DateTime createdAt;
  const WaterParameter({
    required this.id,
    required this.tankId,
    required this.measuredAt,
    this.temperatureCelsius,
    this.ph,
    this.ammoniaPpm,
    this.nitritePpm,
    this.nitratePpm,
    this.ghDgh,
    this.khDkh,
    this.phosphatePpm,
    this.oxygenMgL,
    this.co2MgL,
    this.salinityPpt,
    this.calciumPpm,
    this.magnesiumPpm,
    this.alkalinityDkh,
    this.tdsPpm,
    this.chlorinePpm,
    this.ironPpm,
    this.copperPpm,
    this.notes,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
