    }
    if (!nullToAbsent || oxygenMgL != null) {
      map['oxygen_mg_l'] = Variable<double>(oxygenMgL);
    }
    if (!nullToAbsent || co2MgL != null) {
      map['co2_mg_l'] = Variable<double>(co2MgL);
    }
    if (!nullToAbsent || salinityPpt != null) {
