    if (mediaReplacedAt.present) {
      map['media_replaced_at'] = Variable<DateTime>(mediaReplacedAt.value);
    }
    if (cleaningIntervalDays.present) {
      map['cleaning_interval_days'] = Variable<int>(cleaningIntervalDays.value);
    }
    if (mediaReplacementIntervalDays.present) {
      map['media_replacement_interval_days'] = Variable<int>(
        mediaReplacementIntervalDays.value,
      );
    }
    if (notes.present) {
      map['notes'] = Variable<String>(notes.value);
    }
    if (createdAt.present) {
      map['created_at'] = Variable<DateTime>(createdAt.value);
    }
    if (updatedAt.present) {
      map['updated_at'] = Variable<DateTime>(updatedAt.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('FiltersCompanion(')
          ..write('id: $id, ')
          ..write('tankId: $tankId, ')
          ..write('name: $name, ')
          ..write('filterType: $filterType, ')
          ..write('brand: $brand, ')
          ..write('model: $model, ')
          ..write('flowRateLph: $flowRateLph, ')
          ..write('mediaVolumeLiters: $mediaVolumeLiters, ')
          ..write('lastCleanedAt: $lastCleanedAt, ')
          ..write('mediaReplacedAt: $mediaReplacedAt, ')
          ..write('cleaningIntervalDays: $cleaningIntervalDays, ')
          ..write(
            'mediaReplacementIntervalDays: $mediaReplacementIntervalDays, ',
          )
          ..write('notes: $notes, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }
}

