class Lighting extends DataClass implements Insertable<Lighting> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Light name/label
  final String name;

  /// Lighting type
  final LightingTypeDb lightingType;

  /// Brand name
  final String? brand;

  /// Model number/name
  final String? model;

  /// Power consumption in watts
  final double? wattage;

  /// Color temperature in Kelvin
  final int? kelvinRating;

  /// Light spectrum category
  final LightSpectrumDb? spectrum;

  /// PAR (Photosynthetically Active Radiation) value at substrate
  final int? parValue;

  /// Lumens output
  final int? lumens;

  /// Whether the light is dimmable
  final bool isDimmable;

  /// Whether the light has timer functionality
  final bool hasTimer;

  /// Whether the light has color control (RGB)
  final bool hasColorControl;

  /// Light on time (HH:mm format)
  final String? onTime;

  /// Light off time (HH:mm format)
  final String? offTime;

  /// Current intensity percentage (0-100)
  final int intensityPercent;

  /// Last bulb/LED replacement date
  final DateTime? lastReplacedAt;

  /// Recommended replacement interval in days
  final int replacementIntervalDays;

  /// Notes/additional info
  final String? notes;

  /// Created timestamp
  final DateTime createdAt;

  /// Updated timestamp
  final DateTime updatedAt;
  const Lighting({
    required this.id,
    required this.tankId,
    required this.name,
    required this.lightingType,
    this.brand,
    this.model,
    this.wattage,
    this.kelvinRating,
    this.spectrum,
    this.parValue,
    this.lumens,
    required this.isDimmable,
    required this.hasTimer,
    required this.hasColorControl,
    this.onTime,
    this.offTime,
    required this.intensityPercent,
    this.lastReplacedAt,
    required this.replacementIntervalDays,
    this.notes,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['tank_id'] = Variable<int>(tankId);
    map['name'] = Variable<String>(name);
    {
      map['lighting_type'] = Variable<int>(
        $LightingsTable.$converterlightingType.toSql(lightingType),
      );
    }
    if (!nullToAbsent || brand != null) {
      map['brand'] = Variable<String>(brand);
    }
    if (!nullToAbsent || model != null) {
      map['model'] = Variable<String>(model);
    }
    if (!nullToAbsent || wattage != null) {
      map['wattage'] = Variable<double>(wattage);
    }
    if (!nullToAbsent || kelvinRating != null) {
      map['kelvin_rating'] = Variable<int>(kelvinRating);
    }
    if (!nullToAbsent || spectrum != null) {
      map['spectrum'] = Variable<int>(
        $LightingsTable.$converterspectrumn.toSql(spectrum),
      );
    }
    if (!nullToAbsent || parValue != null) {
      map['par_value'] = Variable<int>(parValue);
    }
    if (!nullToAbsent || lumens != null) {
      map['lumens'] = Variable<int>(lumens);
    }
    map['is_dimmable'] = Variable<bool>(isDimmable);
    map['has_timer'] = Variable<bool>(hasTimer);
    map['has_color_control'] = Variable<bool>(hasColorControl);
    if (!nullToAbsent || onTime != null) {
      map['on_time'] = Variable<String>(onTime);
    }
    if (!nullToAbsent || offTime != null) {
      map['off_time'] = Variable<String>(offTime);
    }
    map['intensity_percent'] = Variable<int>(intensityPercent);
    if (!nullToAbsent || lastReplacedAt != null) {
      map['last_replaced_at'] = Variable<DateTime>(lastReplacedAt);
    }
    map['replacement_interval_days'] = Variable<int>(replacementIntervalDays);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  LightingsCompanion toCompanion(bool nullToAbsent) {
    return LightingsCompanion(
      id: Value(id),
      tankId: Value(tankId),
