class FishData extends DataClass implements Insertable<FishData> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Species scientific name
  final String species;

  /// Common name
  final String? commonName;

  /// Number of this species in tank
  final int quantity;

  /// Water type preference
  final WaterTypeDb waterType;

  /// Fish temperament
  final FishTemperamentDb? temperament;

  /// Diet type
  final FishDietDb? diet;

  /// Care level difficulty
  final CareLevelDb? careLevel;

  /// Swimming level in tank
  final SwimmingLevelDb? swimmingLevel;

  /// Maximum adult size in cm
  final double? maxSizeCm;

  /// Current size in cm
  final double? currentSizeCm;

  /// Minimum tank size in liters
  final double? minTankSizeLiters;

  /// Minimum temperature in Celsius
  final double? minTempCelsius;

  /// Maximum temperature in Celsius
  final double? maxTempCelsius;

  /// Minimum pH
  final double? minPh;

  /// Maximum pH
  final double? maxPh;

  /// Lifespan in years
  final int? lifespanYears;

  /// Date added to tank
  final DateTime? dateAdded;

  /// Date of death (if deceased)
  final DateTime? dateDeceased;

  /// Purchase price
  final double? purchasePrice;

  /// Source/store where purchased
  final String? source;

  /// Is this fish quarantined
  final bool isQuarantined;

  /// Quarantine end date
  final DateTime? quarantineEndDate;

  /// Notes/additional info
  final String? notes;

  /// Photo URL or path
  final String? photoUrl;

  /// Created timestamp
  final DateTime createdAt;

  /// Updated timestamp
  final DateTime updatedAt;
