class Invertebrate extends DataClass implements Insertable<Invertebrate> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Species scientific name
  final String species;

  /// Common name
  final String? commonName;

  /// Type of invertebrate
  final InvertebrateTypeDb invertebrateType;

  /// Number of this species in tank
  final int quantity;

  /// Water type preference
  final InvertWaterTypeDb waterType;

  /// Care level difficulty
  final InvertCareLevelDb? careLevel;

  /// Maximum adult size in cm
  final double? maxSizeCm;

  /// Current size in cm
  final double? currentSizeCm;

  /// Minimum tank size in liters
  final double? minTankSizeLiters;

  /// Minimum temperature in Celsius
  final double? minTempCelsius;

  /// Maximum temperature in Celsius
  final double? maxTempCelsius;

  /// Minimum pH
  final double? minPh;

  /// Maximum pH
  final double? maxPh;

  /// Lifespan in years
  final int? lifespanYears;

  /// Date added to tank
  final DateTime? dateAdded;

  /// Date of death (if deceased)
  final DateTime? dateDeceased;

  /// Purchase price
  final double? purchasePrice;

  /// Source/store where purchased
  final String? source;

  /// Is this invertebrate quarantined
  final bool isQuarantined;

  /// Quarantine end date
  final DateTime? quarantineEndDate;

  /// Is this a breeding colony
  final bool isBreedingColony;

  /// Notes/additional info
  final String? notes;

  /// Photo URL or path
  final String? photoUrl;

  /// Created timestamp
  final DateTime createdAt;

  /// Updated timestamp
  final DateTime updatedAt;
  const Invertebrate({
    required this.id,
    required this.tankId,
    required this.species,
    this.commonName,
    required this.invertebrateType,
    required this.quantity,
    required this.waterType,
    this.careLevel,
    this.maxSizeCm,
    this.currentSizeCm,
    this.minTankSizeLiters,
    this.minTempCelsius,
    this.maxTempCelsius,
    this.minPh,
    this.maxPh,
    this.lifespanYears,
    this.dateAdded,
    this.dateDeceased,
    this.purchasePrice,
    this.source,
    required this.isQuarantined,
    this.quarantineEndDate,
    required this.isBreedingColony,
    this.notes,
    this.photoUrl,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['tank_id'] = Variable<int>(tankId);
    map['species'] = Variable<String>(species);
    if (!nullToAbsent || commonName != null) {
      map['common_name'] = Variable<String>(commonName);
