class SubstrateLayer extends DataClass implements Insertable<SubstrateLayer> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Layer name/label
  final String name;

  /// Type of substrate
  final SubstrateTypeDb substrateType;

  /// Brand name
  final String? brand;

  /// Depth of layer in cm
  final double? depthCm;

  /// Layer order (0 = bottom, higher = top)
  final int layerOrder;

  /// Volume in liters
  final double? volumeLiters;

  /// Weight in kg
  final double? weightKg;

  /// Color of the substrate
  final String? color;

  /// Purchase price
  final double? purchasePrice;

  /// Source/store where purchased
  final String? source;

  /// Date added to tank
  final DateTime? dateAdded;

  /// Photo URL or path
  final String? photoUrl;

  /// Notes/additional info
  final String? notes;

  /// Created timestamp
  final DateTime createdAt;

  /// Updated timestamp
  final DateTime updatedAt;
  const SubstrateLayer({
    required this.id,
    required this.tankId,
    required this.name,
    required this.substrateType,
    this.brand,
    this.depthCm,
    required this.layerOrder,
    this.volumeLiters,
    this.weightKg,
    this.color,
    this.purchasePrice,
    this.source,
    this.dateAdded,
    this.photoUrl,
    this.notes,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['tank_id'] = Variable<int>(tankId);
    map['name'] = Variable<String>(name);
    {
      map['substrate_type'] = Variable<int>(
        $SubstrateLayersTable.$convertersubstrateType.toSql(substrateType),
      );
    }
    if (!nullToAbsent || brand != null) {
      map['brand'] = Variable<String>(brand);
    }
    if (!nullToAbsent || depthCm != null) {
      map['depth_cm'] = Variable<double>(depthCm);
    }
    map['layer_order'] = Variable<int>(layerOrder);
    if (!nullToAbsent || volumeLiters != null) {
      map['volume_liters'] = Variable<double>(volumeLiters);
    }
    if (!nullToAbsent || weightKg != null) {
      map['weight_kg'] = Variable<double>(weightKg);
    }
    if (!nullToAbsent || color != null) {
      map['color'] = Variable<String>(color);
    }
    if (!nullToAbsent || purchasePrice != null) {
      map['purchase_price'] = Variable<double>(purchasePrice);
    }
    if (!nullToAbsent || source != null) {
      map['source'] = Variable<String>(source);
    }
    if (!nullToAbsent || dateAdded != null) {
      map['date_added'] = Variable<DateTime>(dateAdded);
    }
    if (!nullToAbsent || photoUrl != null) {
      map['photo_url'] = Variable<String>(photoUrl);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  SubstrateLayersCompanion toCompanion(bool nullToAbsent) {
    return SubstrateLayersCompanion(
      id: Value(id),
      tankId: Value(tankId),
      name: Value(name),
      substrateType: Value(substrateType),
      brand: brand == null && nullToAbsent
          ? const Value.absent()
          : Value(brand),
      depthCm: depthCm == null && nullToAbsent
          ? const Value.absent()
          : Value(depthCm),
      layerOrder: Value(layerOrder),
