class Plant extends DataClass implements Insertable<Plant> {
  /// Primary key
  final int id;

  /// Foreign key to tanks table
  final int tankId;

  /// Species scientific name
  final String species;

  /// Common name
  final String? commonName;

  /// Type of plant
  final PlantTypeDb plantType;

  /// Number of this species in tank
  final int quantity;

  /// Placement zone in tank
  final PlacementZoneDb? placementZone;

  /// Lighting requirement
  final LightingRequirementDb? lightingRequirement;

  /// CO2 requirement
  final CO2RequirementDb co2Requirement;

  /// Growth rate
  final GrowthRateDb? growthRate;

  /// Difficulty level
  final PlantDifficultyLevelDb? difficultyLevel;

  /// Maximum height in cm
  final double? maxHeightCm;

  /// Current height in cm
  final double? currentHeightCm;

  /// Minimum temperature in Celsius
  final double? minTempCelsius;

  /// Maximum temperature in Celsius
  final double? maxTempCelsius;

  /// Minimum pH
  final double? minPh;

  /// Maximum pH
  final double? maxPh;

  /// Date added to tank
  final DateTime? dateAdded;

  /// Date removed from tank
  final DateTime? dateRemoved;

  /// Is this plant propagated from another
  final bool isPropagated;

  /// Parent plant ID (if propagated)
  final int? parentPlantId;

  /// Purchase price
  final double? purchasePrice;

  /// Source/store where purchased
  final String? source;

  /// Notes/additional info
  final String? notes;

  /// Photo URL or path
  final String? photoUrl;

  /// Created timestamp
  final DateTime createdAt;

  /// Updated timestamp
  final DateTime updatedAt;
  const Plant({
    required this.id,
    required this.tankId,
    required this.species,
    this.commonName,
    required this.plantType,
    required this.quantity,
    this.placementZone,
    this.lightingRequirement,
    required this.co2Requirement,
    this.growthRate,
    this.difficultyLevel,
