    this.currentHeightCm,
    this.minTempCelsius,
    this.maxTempCelsius,
    this.minPh,
    this.maxPh,
    this.dateAdded,
    this.dateRemoved,
    required this.isPropagated,
    this.parentPlantId,
    this.purchasePrice,
    this.source,
    this.notes,
    this.photoUrl,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
