          })
        > {
  $$TanksTableTableManager(_$AppDatabase db, $TanksTable table)
    : super(
        TableManagerState(
          db: db,
          table: table,
          createFilteringComposer: () =>
              $$TanksTableFilterComposer($db: db, $table: table),
          createOrderingComposer: () =>
              $$TanksTableOrderingComposer($db: db, $table: table),
          createComputedFieldComposer: () =>
              $$TanksTableAnnotationComposer($db: db, $table: table),
          updateCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                Value<String> name = const Value.absent(),
                Value<TankType> tankType = const Value.absent(),
                Value<double> volumeLiters = const Value.absent(),
                Value<double?> lengthCm = const Value.absent(),
                Value<double?> widthCm = const Value.absent(),
                Value<double?> heightCm = const Value.absent(),
                Value<String?> description = const Value.absent(),
                Value<String?> photoPath = const Value.absent(),
                Value<DateTime?> setupDate = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
              }) => TanksCompanion(
                id: id,
                name: name,
                tankType: tankType,
                volumeLiters: volumeLiters,
                lengthCm: lengthCm,
                widthCm: widthCm,
                heightCm: heightCm,
                description: description,
                photoPath: photoPath,
                setupDate: setupDate,
                isActive: isActive,
                createdAt: createdAt,
                updatedAt: updatedAt,
              ),
          createCompanionCallback:
              ({
                Value<int> id = const Value.absent(),
                required String name,
                required TankType tankType,
                required double volumeLiters,
                Value<double?> lengthCm = const Value.absent(),
                Value<double?> widthCm = const Value.absent(),
                Value<double?> heightCm = const Value.absent(),
                Value<String?> description = const Value.absent(),
                Value<String?> photoPath = const Value.absent(),
                Value<DateTime?> setupDate = const Value.absent(),
                Value<bool> isActive = const Value.absent(),
                Value<DateTime> createdAt = const Value.absent(),
                Value<DateTime> updatedAt = const Value.absent(),
              }) => TanksCompanion.insert(
                id: id,
                name: name,
                tankType: tankType,
                volumeLiters: volumeLiters,
                lengthCm: lengthCm,
                widthCm: widthCm,
                heightCm: heightCm,
                description: description,
                photoPath: photoPath,
                setupDate: setupDate,
